From 24e470b5c15f62deadc1fa105d70ac2e8a32650a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 02:26:29 +0100
Subject: [PATCH] applets/taskmanager: add an option for what Ctrl+clicking a
 grouped task does

Ctrl+clicking a grouped task always did the same as clicking it, so there
was no way to, for example, cycle through windows on click and still get a
textual list or window previews. Add a setting that picks the action for it.

BUG: 437793
---
 applets/taskmanager/main.xml               |  4 +++
 applets/taskmanager/qml/ConfigBehavior.qml | 41 +++++++++++++++++++++-
 applets/taskmanager/qml/code/TaskTools.js  | 11 ++++--
 3 files changed, 52 insertions(+), 4 deletions(-)

diff --git a/applets/taskmanager/main.xml b/applets/taskmanager/main.xml
index 8c3b68785b..52aba8765b 100644
--- a/applets/taskmanager/main.xml
+++ b/applets/taskmanager/main.xml
@@ -34,6 +34,10 @@
       <label>What happens when clicking on a grouped task: 0 = cycle through grouped tasks, 1 = try to show tooltips, 2 = try to show present Windows effect, 3 = show textual list (AKA group dialog)</label>
       <default>0</default>
     </entry>
+    <entry name="groupedTaskCtrlClickVisualization" type="Int">
+      <label>What happens when Ctrl+clicking on a grouped task: -1 = the same as clicking, otherwise like groupedTaskVisualization</label>
+      <default>-1</default>
+    </entry>
     <entry name="groupPopups" type="Bool">
       <label>Whether groups are to be reduced to a single task button and expand into a popup or task buttons are grouped on the widget itself.</label>
       <default>true</default>
diff --git a/applets/taskmanager/qml/ConfigBehavior.qml b/applets/taskmanager/qml/ConfigBehavior.qml
index bd4b7cf008..3a4103cbaa 100644
--- a/applets/taskmanager/qml/ConfigBehavior.qml
+++ b/applets/taskmanager/qml/ConfigBehavior.qml
@@ -21,6 +21,7 @@ KCMUtils.SimpleKCM {

     property alias cfg_groupingStrategy: groupingStrategy.currentIndex
     property alias cfg_groupedTaskVisualization: groupedTaskVisualization.currentIndex
+    property int cfg_groupedTaskCtrlClickVisualization
     property alias cfg_groupPopups: groupPopups.checked
     property alias cfg_onlyGroupWhenFull: onlyGroupWhenFull.checked
     property int cfg_sortingStrategy
@@ -90,10 +91,48 @@ KCMUtils.SimpleKCM {
             Accessible.name: currentText
             Accessible.onPressAction: currentIndex = currentIndex === count - 1 ? 0 : (currentIndex + 1)
         }
+        QQC2.ComboBox {
+            id: groupedTaskCtrlClickVisualization
+            Kirigami.FormData.label: i18nc("@label:listbox completes sentence like: … cycles through tasks", "Ctrl+clicking grouped task:")
+            Layout.fillWidth: true
+            Layout.minimumWidth: Kirigami.Units.gridUnit * 14
+
+            enabled: groupingStrategy.currentIndex !== 0
+
+            textRole: "text"
+            valueRole: "value"
+            model: [
+                {
+                    "text": i18nc("@item:inlistbox Completes the sentence 'Ctrl+clicking grouped task does the same as clicking' ", "Does the same as clicking"),
+                    "value": -1,
+                },
+                {
+                    "text": i18nc("@item:inlistbox Completes the sentence 'Ctrl+clicking grouped task cycles through tasks' ", "Cycles through tasks"),
+                    "value": 0,
+                },
+                {
+                    "text": i18nc("@item:inlistbox Completes the sentence 'Ctrl+clicking grouped task shows small window previews' ", "Shows small window previews"),
+                    "value": 1,
+                },
+                {
+                    "text": i18nc("@item:inlistbox Completes the sentence 'Ctrl+clicking grouped task shows large window previews' ", "Shows large window previews"),
+                    "value": 2,
+                },
+                {
+                    "text": i18nc("@item:inlistbox Completes the sentence 'Ctrl+clicking grouped task shows textual list' ", "Shows textual list"),
+                    "value": 3,
+                },
+            ]
+
+            onActivated: root.cfg_groupedTaskCtrlClickVisualization = currentValue
+            Component.onCompleted: currentIndex = indexOfValue(root.cfg_groupedTaskCtrlClickVisualization)
+
+            Accessible.name: currentText
+        }
         // "You asked for Window View but Window View is not available" message
         Kirigami.InlineMessage {
             Layout.fillWidth: true
-            visible: groupedTaskVisualization.currentIndex === 2 && !effectWatcher.registered
+            visible: (groupedTaskVisualization.currentIndex === 2 || groupedTaskCtrlClickVisualization.currentValue === 2) && !effectWatcher.registered
             type: Kirigami.MessageType.Warning
             text: i18nc("@info displayed as InlineMessage", "The compositor does not support displaying windows side by side, so a textual list will be displayed instead.")
         }
diff --git a/applets/taskmanager/qml/code/TaskTools.js b/applets/taskmanager/qml/code/TaskTools.js
index 8f8adadd6f..e8421c26fe 100644
--- a/applets/taskmanager/qml/code/TaskTools.js
+++ b/applets/taskmanager/qml/code/TaskTools.js
@@ -127,13 +127,18 @@ function activateTask(index, model, modifiers, task, plasmoid, tasks, windowView
     }

     if (model.IsGroupParent) {
+        let visualization = plasmoid.configuration.groupedTaskVisualization;
+        if ((modifiers & Qt.ControlModifier) && plasmoid.configuration.groupedTaskCtrlClickVisualization >= 0) {
+            visualization = plasmoid.configuration.groupedTaskCtrlClickVisualization;
+        }
+
         // Option 1 (default): Cycle through this group's tasks
         // ====================================================
         // If the grouped task does not include the currently active task, bring
         // forward the most recently used task in the group.
         // Otherwise cycle through all tasks in the group without paying attention
         // to the last activation time, which otherwise would change with every click
-        if (plasmoid.configuration.groupedTaskVisualization === 0) {
+        if (visualization === 0) {
             let childTaskList = [];

             for (let i = 0; i < tasks.tasksModel.rowCount(task.modelIndex(index)); ++i) {
@@ -175,7 +180,7 @@ function activateTask(index, model, modifiers, task, plasmoid, tasks, windowView

         // Option 2: show tooltips for all child tasks
         // ===========================================
-        else if (plasmoid.configuration.groupedTaskVisualization === 1) {
+        else if (visualization === 1) {
             if (tasks.toolTipOpenedByClick) {
                 task.hideImmediately();
             } else {
@@ -189,7 +194,7 @@ function activateTask(index, model, modifiers, task, plasmoid, tasks, windowView
         // ==================================================
         // Make sure the Window View effect is  are actually enabled though;
         // if not, fall through to the next option.
-        else if (plasmoid.configuration.groupedTaskVisualization === 2 && windowViewAvailable) {
+        else if (visualization === 2 && windowViewAvailable) {
             task.hideToolTip();
             tasks.activateWindowView(model.WinIdList);
         }
-- 
2.53.0
